window.CERT_DATA=window.CERT_DATA||{};window.CERT_DATA['adsp-40']={"round":40,"cert":"adsp","questions":[{"id":"62444","number":1,"category":"데이터 이해","type":"choice","subject":"다음 중 기업의 전략 도출을 위한 가치 기반 분석과 관련된 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"핵심적인 비즈니스 이슈에 답을 주는 분석은 기업의 경쟁 전략과 밀접하게 연관된다."},{"n":2,"html":"다양한 대량의 데이터를 수집, 분석하여 새로운 정보나 인사이트를 도출하고, 이를 기반으로 비즈니스 가치를 창출하는 것이 중요하다."},{"n":3,"html":"전략적 분석과 통찰력의 창출은 빅데이터 프로젝트에서 핵심적인 역할을 한다."},{"n":4,"html":"기존 성과를 유지하고 업계를 따라잡는 것이 전략적 가치 기반 분석의 가장 중요한 목표이다."}],"answer":[4],"explain":{"ai":["<p>정답은 4번입니다. 가치 기반 분석의 주요 목표는 단순히 기존 성과 유지와 업계 평균을 따라잡는 것이 아니라, 더 나아가 차별화된 경쟁 우위를 확보하고 새로운 비즈니스 기회를 발굴하는 데 있습니다. 따라서 기업은 시장 변화에 민감하게 반응하고 혁신적인 전략을 통해 가치를 극대화하려 노력해야 하며, 이는 단순히 따라잡기 수준을 넘어섭니다. 1, 2, 3번은 모두 가치 기반 분석의 핵심 요소와 일치하는 설명입니다: 비즈니스 이슈 해결, 데이터 기반 인사이트 창출, 그리고 빅데이터를 통한 전략적 의사결정의 중요성 강조 등이 포함되어 있습니다.</p>"]},"rate":87,"rateN":11924},{"id":"62445","number":2,"category":"데이터 이해","type":"choice","subject":"빅데이터 분석 활용의 효과 예시로 가장 옳지 않은 것은?","choices":[{"n":1,"html":"운송 비용의 절감"},{"n":2,"html":"상품 개발과 조립 비용의 절감"},{"n":3,"html":"서비스 산업의 확대와 제조업의 축소"},{"n":4,"html":"새로운 수익원의 발굴 및 활용"}],"answer":[3],"explain":{"ai":["<p>정답은 3번입니다. 빅데이터 분석은 주로 효율성 향상, 비용 절감, 그리고 새로운 기회 탐색에 중점을 둡니다. </p>\n<p>1번의 운송 비용 절감은 물류 최적화를 통해 가능합니다. \n2번의 상품 개발 및 조립 비용 절감은 데이터 기반의 생산 효율성 개선으로 달성될 수 있습니다. \n4번의 새로운 수익원 발굴은 고객 행동 분석과 시장 트렌드 예측을 통해 이루어집니다.</p>\n<p>반면, 3번의 \"서비스 산업의 확대와 제조업의 축소\"는 빅데이터 분석 자체의 직접적인 효과라기보다는 시장 변화, 경제적 요인, 정책 등 다양한 외부 요인에 의해 주도되는 경향입니다. 빅데이터는 각 산업 내에서의 효율성과 혁신을 촉진할 수 있지만, 특정 산업의 확대와 다른 산업의 축소를 직접적으로 유발하는 것은 그 범위를 벗어난 해석입니다. 따라서 가장 옳지 않은 예시는 3번입니다.</p>"]},"rate":73,"rateN":12702},{"id":"62446","number":3,"category":"데이터 이해","type":"choice","subject":"데이터베이스의 일반적인 특징으로 옳지 않은 것은?","choices":[{"n":1,"html":"데이터베이스는 다수가 공동으로 이용하는 공용 데이터이다."},{"n":2,"html":"데이터베이스는 응용프로그램의 종속성을 가진다."},{"n":3,"html":"데이터베이스는 컴퓨터가 접근 가능한 저장매체에 데이터를 저장한다"},{"n":4,"html":"데이터베이스는 동일한 내용의 데이터가 중복되지 않는 통합 데이터이다."}],"answer":[2],"explain":{"ai":["<p>정답인 2번은 데이터베이스의 일반적인 특징으로 옳지 않다. 데이터베이스는 응용프로그램에 종속되지 않으며, 독립적으로 존재하여 다양한 응용프로그램에서 접근할 수 있다. </p>\n<p>그리고 다른 보기 중 1번은 데이터베이스가 다수가 공동으로 이용하는 공용 데이터라는 것을 말해준다. 3번은 데이터베이스가 컴퓨터가 접근 가능한 저장매체에 데이터를 저장한다는 것을 말해주며, 4번은 데이터베이스가 동일한 내용의 데이터가 중복되지 않는 통합 데이터라는 것을 말해준다.</p>"]},"rate":80,"rateN":11483},{"id":"62447","number":4,"category":"데이터 이해","type":"choice","subject":"다음 중 기업 내부 데이터베이스 솔루션으로 알맞지 않은 것은?","choices":[{"n":1,"html":"ERP"},{"n":2,"html":"ITS"},{"n":3,"html":"SCM"},{"n":4,"html":"CRM"}],"answer":[2],"explain":{"ai":["<p>기업 내부 데이터베이스 솔루션으로는 일반적으로 ERP, SCM, CRM이 있다. \nERP는 엔터프라이즈 리소스 플래닝의 약자로, 기업의 핵심 기능을 지원하기 위한 통합 시스템을 말한다. \nSCM은 서플라이 체인 매니지먼트의 약자로, 기업의 공급망을 관리하기 위한 솔루션을 말한다. \nCRM은 고객 관계 관리의 약자로, 고객 정보를 관리하고 분석하기 위한 솔루션을 말한다. \nITS는 인텔리전트 트래픽 시스템의 약자로, 교통 관제 시스템을 말한다. \n따라서 ITS는 기업 내부 데이터베이스 솔루션이 아니다.</p>"]},"rate":77,"rateN":11966},{"id":"62448","number":5,"category":"데이터 이해","type":"choice","subject":"데이터 특징에 대한 설명 중 옳지 않은 것은?","choices":[{"n":1,"html":"데이터는 객관적 사실이다."},{"n":2,"html":"데이터는 추론과 추정의 근거를 이루는 사실이다."},{"n":3,"html":"데이터의 최소단위는 바이트로 0과1의 이진수 하나로 이루어져 있다."},{"n":4,"html":"단순한 객체로서의 가치와 다른 객체와의 상호 관계 속에서 가치를 갖는다."}],"answer":[3],"explain":{"ai":["<p>데이터 특징에 대한 설명 중 옳지 않은 것은 3번입니다. </p>\n<p>데이터의 최소 단위를 바이트로 정의하며 이진수 0과 1 하나로만 설명하는 것은 \n부정확합니다. 바이트는 실제로 8비트, 즉 8개의 이진수(0 또는 1)로 구성됩니다. 따라서, \n데이터의 최소 단위를 단순히 한 개의 이진수로만 표현하는 것은 정확하지 않습니다. </p>\n<p>나머지 설명들은 올바릅니다:</p>\n<ol>\n<li>데이터는 주관적인 해석 없이 객관적인 사실을 담고 있습니다.</li>\n<li>데이터는 분석과 추론의 기반이 되는 중요한 사실입니다.</li>\n<li>데이터는 자체적인 가치뿐만 아니라 다른 데이터와의 관계 속에서도 의미를 갖습니다.</li>\n</ol>"]},"rate":60,"rateN":13126},{"id":"62449","number":6,"category":"데이터 이해","type":"choice","subject":"이미지, 로그, 영상, 텍스트 등의 데이터 형태로 알맞은 것은?","choices":[{"n":1,"html":"Structured data"},{"n":2,"html":"Qualitative data"},{"n":3,"html":"Unstructured data"},{"n":4,"html":"Semi-Structured data"}],"answer":[3],"explain":{"ai":["<p>이미지, 로그, 영상, 텍스트 등은 정형화되지 않은 데이터를 의미한다. 이러한 데이터 형태는 구조화되지 않은 데이터로 분류된다. </p>\n<p>구조화되지 않은 데이터란, 미리 정의된 형식에 따라 저장되거나 조직되지 않는 데이터를 말한다. 이미지, 로그, 영상, 텍스트는 이에 해당한다. 정형화된 데이터와 반대되는 개념으로, 데이터베이스 등의 표에 저장되기 어려운 데이터를 가리킨다. </p>\n<p>이와 반대로 구조화된 데이터는 미리 정의된 형식에 따라 저장되거나 조직되는 데이터를 말한다. 예를 들어ุลาคม, 이름, 주소 등이 있다. 반構造화된 데이터는 두 가지의 중간 정도의 데이터 형태를 말한다. 예를 들어서 xml이나 json과 같은 데이터 형태가 있다. </p>\n<p>질적 데이터란, 수치로 변환할 수 없는 데이터를 말한다. 예를 들어서 고객의滿意도, 취미 등이 있다. </p>\n<p>따라서 이미지, 로그, 영상, 텍스트 등의 데이터 형태로 알맞은 것은 구조화되지 않은 데이터이다.</p>"]},"rate":79,"rateN":11449},{"id":"62450","number":7,"category":"데이터 이해","type":"choice","subject":"다음 중 빅데이터 활용 기법에 관한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"군집분석을 통해 고객의 개인 신용 평가에 활용한다.(신용 예측에 활용한다.)"},{"n":2,"html":"최적화 문제에 대한 해결 방안으로 사용되는 빅데이터 분석은 유전 알고리즘이다."},{"n":3,"html":"특정 주제에 대해 사용되는 텍스트를 분석하는 것을 감정(성)분석이라 한다."},{"n":4,"html":"최근 핀테크 기업들은 사회연결망 분석을 활용하고 있다."}],"answer":[1],"explain":{"ai":["<p>군집분석은 고객들의 특징을 군집화하여 그룹화 하는 것을 의미한다. 하지만 개인 신용 등을 평가하는 것은 개인의 신용 등급을 예측하기 위한 분석으로 개인의 정보를 기반으로 분석된다. 따라서 군집분석은 개인의 신용평가에는 적합하지 않다. </p>\n<p>반면에 유전 알고리즘은 문제 해결을 위해 진화와 자연선택의 메커니즘을 사용하므로 다양한 최적화 문제에 활용이 가능하다. 또한 감정분석은 텍스트나 소셜 미디어의 texto 등을分析하여 고객의 감정이나 의견을 파악하는 것을 의미하므로 특정 주제에 대한 텍스트 분석에도 활용이 가능하다. 마지막으로 사회연결망 분석은 개인간의 관계나 네트워크를 분석하여 활용하는 것으로 핀테크 기업에서도 다양한 목적으로 활용되고 있다.</p>"]},"rate":50,"rateN":13976},{"id":"62451","number":8,"category":"데이터 이해","type":"choice","subject":"빅데이터가 만들어 낸 본질적인 변화로 옳지 않은 것은?","extra":"<pre class=\"contents\">가. 사전처리 → 사후처리\r\n나. 대면조사 → 표본조사\r\n다. 질보다 → 양적으로\r\n라. 상관관계 → 인과관계</pre>","choices":[{"n":1,"html":"가, 나"},{"n":2,"html":"나, 라"},{"n":3,"html":"다, 라"},{"n":4,"html":"가, 라"}],"answer":[2],"explain":{"ai":["<p>빅데이터 환경에서 본질적인 변화를 살펴보면, 올바른 전환은 데이터 처리 방식, 조사 방법, 그리고 분석의 초점 변화 등에 집중된다. </p>\n<ul>\n<li><strong>가. 사전처리 → 사후처리</strong>: 빅데이터는 데이터 규모가 방대해져 사전에 모든 정제를 하기 어려워 사후처리의 중요성이 증가한다. 따라서 이는 맞는 변화이다.</li>\n<li><strong>나. 대면조사 → 표본조사</strong>: 빅데이터는 대량의 데이터를 기반으로 하므로, 전통적인 대면조사보다 대규모 표본조사나 전체 데이터 분석이 가능해져 이 또한 올바른 변화다.</li>\n<li><strong>다. 질보다 → 양적으로</strong>: 빅데이터는 데이터의 양적 측면이 질적 측면을 넘어서 중요한 역할을 하게 되므로, 이 역시 본질적인 변화 중 하나다.</li>\n<li><strong>라. 상관관계 → 인과관계</strong>: 빅데이터는 많은 패턴과 상관관계를 발견하는 데 유용하지만, 단순히 상관관계를 찾아냈다고 해서 쉽게 인과관계를 확정 짓기는 어렵다. 이는 빅데이터의 본질적 한계로, 옳지 않은 변화로 볼 수 있다.</li>\n</ul>\n<p>따라서 옳지 않은 변화를 포함한 옵션은 <strong>나, 라</strong>로, 정답은 <strong>2번</strong>이다.</p>"]},"rate":77,"rateN":11469},{"id":"62452","number":9,"category":"데이터 이해","type":"choice","subject":"가트너가 본 데이터 사이언티스트의 요구 역량으로 알맞지 않은 것은?","choices":[{"n":1,"html":"데이터 관리"},{"n":2,"html":"분석 모델링"},{"n":3,"html":"비즈니스 분석"},{"n":4,"html":"조직 관리"}],"answer":[4],"explain":{"ai":["<p>데이터 사이언티스트의 핵심 역량은 주로 데이터 관련 기술과 분석 능력에 초점을 맞춥니다. </p>\n<ol>\n<li><strong>데이터 관리</strong>: 데이터 수집, 정제, 저장 등 데이터의 생명 주기 관리 능력은 필수적입니다.</li>\n<li><strong>분석 모델링</strong>: 복잡한 데이터로부터 의미 있는 패턴을 찾아내고 예측 모델을 구축하는 기술이 중요합니다.</li>\n<li><strong>비즈니스 분석</strong>: 데이터를 통해 비즈니스 문제를 해결하고 의사결정을 지원하는 능력 또한 핵심 역량 중 하나입니다.</li>\n</ol>\n<p>반면, \n4. <strong>조직 관리</strong>: 이는 일반적으로 경영진이나 중간 관리자의 역할에 더 가깝습니다. 데이터 사이언티스트의 주요 업무는 기술적 분석과 모델링에 집중되어 있어, 조직 내 인적 자원 관리나 전략적 조직 운영과 같은 조직 관리 역량은 그들의 핵심 요구 역량에 포함되지 않습니다. 따라서 알맞지 않은 역량은 4번, 조직 관리입니다.</p>"]},"rate":71,"rateN":12614},{"id":"62453","number":10,"category":"데이터 이해","type":"choice","subject":"다음 중 데이터 사이언티스트에게 요구되는 하드 스킬로 알맞은 것은?","choices":[{"n":1,"html":"데이터 분석 기술"},{"n":2,"html":"시각화를 활용한 설득력"},{"n":3,"html":"커뮤니케이션 기술"},{"n":4,"html":"창의적 사고"}],"answer":[1],"explain":{"ai":["<p>データ 사이언티스트에게 요구되는 하드 스킬은 주로 기술적인 부분을 의미한다. 데이터 사이언티스트는 데이터를 수집하고 분석하며 이를 통해 정보를 추출하고 모델을 생성하는 일을 한다.따라서 데이터 분석 기술이 가장 적절한答案이다. </p>\n<p>데이터 분석 기술에는 통계적 분석, 머신러닝, 데이터 시각화, 데이터 처리 등이 포함된다. 데이터 사이언티스트는 이러한 기술들을 활용하여 데이터를분석하고 결과를 도출한다. </p>\n<p>시각화를 활용한 설득력, 커뮤니케이션 기술, 창의적 사고는 데이터 사이언티스트에게 важ하지만 소프트 스킬에 해당한다. 소프트 스킬은 기술적인 능력보다는 개인의 상대나 팀워크, 문제 해결 능력 등을 포함한다.</p>"]},"rate":88,"rateN":10680},{"id":"62454","number":11,"category":"데이터 분석 기획","type":"choice","subject":"조직에 대한 분석 문화를 자리 잡게 하기 위한 행동으로 알맞지 않은 것은?","choices":[{"n":1,"html":"경영진이 데이터에 기반 한 의사결정을 할 수 있는 기업문화 정착의 변화관리를 지속해야 한다."},{"n":2,"html":"분석적인 사고를 업무에 적용할 수 있도록 다양한 교육을 실시해야 한다."},{"n":3,"html":"단순한 도구(Tool) 교육이 아닌 분석 역량의 확보와 강화에 초점을 맞춰야 한다."},{"n":4,"html":"경영진을 대상으로 한시적 속성 교육을 강화해야 한다."}],"answer":[4],"explain":{"ai":["<p>조직에 대한 분석 문화를 자리 잡게 하기 위해서는 여러 가지 행동이 필요하다. 경영진이 데이터에 기반한 의사결정을 할 수 있는 기업문화를 정착시키고 बदल어 나가는 과정이 중요하다. 또한 분석적인 사고를 업무에 적용할 수 있도록 다양한 교육을 실시하여 직원들이 데이터를 분석하고 해석할 수 있는 능력을 강화하는 것이 필요하다. 단순한 도구 교육이 아닌 분석 역량의 확보와 강화에 초점을 맞추는 것도 중요하다.</p>\n<p>하지만 경영진을 대상으로 한시적 속성 교육을 강화하는 것은 분석 문화를 자리 잡게 하는 데 알맞지 않은 행동이다. 분석 문화를 자리 잡게 하기 위해서는 지속적이고 종합적인 접근이 필요하다. 한시적 속성 교육은 분석 문화를 자리 잡게 하는 데 필요한 지속성과 종합성을 제공하지 못한다. 따라서 4번이 정답이다.</p>"]},"rate":94,"rateN":9425},{"id":"62455","number":12,"category":"데이터 분석 기획","type":"choice","subject":"아래에서 설명한 데이터 분석 조직 구조는?","extra":"<pre class=\"contents\">- 전사 분석업무를 별도의 분석 전담 조직에서 담당\r\n- 전략적 중요도에 따라 분석 조직이 우선 순위를 정해서 진행 가능\r\n- 현업 업무부서의 분석 업무와 이중화/이원화 가능성 높음</pre>","choices":[{"n":1,"html":"집중 구조"},{"n":2,"html":"기능 구조"},{"n":3,"html":"확산 구조"},{"n":4,"html":"분산 구조"}],"answer":[1],"explain":{"ai":["<p>해설은 이렇게rollo \n전사 분석 업무를 별도의 분석 전담 조직에서 담당하는 조직 구조는 집중 구조로 전략적 중요도에 따라 우선순위를 정해서 진행할 수 있고 현업 업무 부서의 분석 업무와 이중화나 이원화의 가능성이 높은 구조입니다. 따라서 정답은 집중 구조입니다.</p>"]},"rate":69,"rateN":11410},{"id":"62456","number":13,"category":"데이터 분석 기획","type":"choice","subject":"빅데이터 분석 방법론의 분석 기획 단계 산출물인 프로젝트 범위 정의서(SOW)에 들어가는 내용으로 옳은 것은?","choices":[{"n":1,"html":"비즈니스 이해"},{"n":2,"html":"데이터 정의"},{"n":3,"html":"데이터 스토어 설계"},{"n":4,"html":"탐색적 분석"}],"answer":[1],"explain":{"ai":["<p>빅데이터 분석 방법론의 분석 기획 단계에서 중요한 산출물은 프로젝트 범위 정의서이다. 프로젝트 범위 정의서에는 분석 대상 범위, 목표, 요구사항 등을 정의하여 분석 프로젝트의 방향을 결정한다. </p>\n<p>이 중 비즈니스 이해는 프로젝트 범위 정의서의 핵심 내용이다. 비즈니스 이해는 분석의 목적과 요구사항을 명확히 하는데 중요한 역할을 하며, 이후 분석을 위한 데이터 수집과 처리 방향을 결정하는데도 중요한 기준이 된다. </p>\n<p>데이터 정의, 데이터 스토어 설계, 탐색적 분석은 분석 프로젝트에서 중요한 단계이나 프로젝트 범위 정의서에 직접적으로 포함되는 내용은 아니다. 프로젝트 범위 정의서에는 분석의 목적, 범위, 요구사항 等을 정의하는 내용이 포함되며, 비즈니스 이해는 이에 해당한다. </p>\n<p>따라서 프로젝트 범위 정의서에 들어가는 내용으로 옳은 것은 비즈니스 이해이다.</p>"]},"rate":48,"rateN":13523},{"id":"62458","number":14,"category":"데이터 분석 기획","type":"choice","subject":"다음 중 CRISP-DM의 모델링 단계에서 수행하는 업무(TASK)로 옳지 않은 것은?","choices":[{"n":1,"html":"모델링 기법 선택"},{"n":2,"html":"데이터 통합"},{"n":3,"html":"모델 테스트 계획 설계"},{"n":4,"html":"모델 평가"}],"answer":[2],"explain":{"ai":["<p>CRISP-DM은 데이터 마이닝 프로젝트를 체계적으로 수행하기 위한 모형으로 데이터 이해, 데이터 준비, 모델링, 평가, 배포의 5가지 단계로 구성된다. 모델링 단계에서는 데이터를 분석하여 패턴이나 관계를 찾기 위한 기법을 선정하고 적용하며 모델을 평가하는 업무를 수행한다.</p>\n<p>모델링 단계에서 수행하는 업무는 모델링 기법 선택, 모델 테스트 계획 설계, 모델링, 모델 평가 등이 있다. 모델링 기법 선택은 모델링에 사용할 알고리즘과 기법을 결정하는 절차이다. 모델 테스트 계획 설계는 모델을 테스트하고 평가하기 위한 계획을 수립하는 과정이다. 모델링은 실제로 데이터를 분석하여 모델을 구축하는 단계이다. 모델 평가는 개발된 모델의 성능과 품질을 평가하여 모델이 문제를 잘 해결하는지 확인하는 단계이다.</p>\n<p>그러나 데이터 통합은 모델링 이전의 단계인 데이터 준비 단계에서 수행되는 업무이다. 데이터 통합은 다수의 데이터来源에서 데이터를 수집하여 하나의 데이터 세트로 만드는 과정이다. 따라서 모델링 단계에서 수행하는 업무 중 데이터 통합은 옳지 않은 것이다.</p>"]},"rate":57,"rateN":12422},{"id":"62457","number":15,"category":"데이터 분석 기획","type":"choice","subject":"빅데이터 분석 절차는 빅데이터 분석 방법론을 토대로 5단계 절차로 수행된다. 절차로 옳은 것은?","choices":[{"n":1,"html":"분석 기획 → 데이터 준비 → 시스템 구현 → 데이터 분석 → 평가 및 전개"},{"n":2,"html":"분석 기획 → 데이터 분석 → 시스템 구현 → 데이터 준비 → 평가 및 전개"},{"n":3,"html":"데이터 준비 → 분석 기획 → 데이터 분석 → 시스템 구현 → 평가 및 전개"},{"n":4,"html":"분석 기획 → 데이터 준비 → 데이터 분석 → 시스템 구현 → 평가 및 전개"}],"answer":[4],"explain":{"ai":["<p>빅데이터 분석 절차는 일반적으로 5단계로 구성되며 각 단계는 순차적으로 진행된다. 첫 번째 단계는 분석 기획으로 어떤 문제를 풀고자 하는지 정의하고 목표를 설정하는 단계이다. 두 번째 단계는 데이터 준비로 필요한 데이터를 수집하고 처리하는 단계이다. 세 번째 단계는 데이터 분석으로 실제 데이터 분석을 수행하는 단계이다. 네 번째 단계는 시스템 구현으로 분석한 결과를 바탕으로 시스템을 구축하는 단계이다. 마지막 단계는 평가 및 전개로 분석 결과와 시스템을 평가하고 전개하는 단계이다. 따라서 빅데이터 분석 절차는 분석 기획, 데이터 준비, 데이터 분석, 시스템 구현, 평가 및 전개 순으로 진행된다.</p>"]},"rate":77,"rateN":10621},{"id":"62459","number":16,"category":"데이터 분석 기획","type":"choice","subject":"분석 과제 발굴 방법 중 상향식 접근법(Bottom Up Approach)에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"분석 대상이 명확할 때 솔루션을 찾는 방식이다."},{"n":2,"html":"일반적으로 비지도 학습(Unsupervised Learning) 방식을 수행한다."},{"n":3,"html":"다양한 원천 데이터를 대상으로 분석을 수행하여 가치 있는 문제를 도출하는 일련의 과정이다."},{"n":4,"html":"하향식 접근 방식과는 달리 복잡하고 다양한 환경에서 발생하는 문제 해결에도 적합하다."}],"answer":[1],"explain":{"ai":["<p>상향식 접근법은 다양한 원천 데이터를 분석하여 가치 있는 문제를 찾아내는 방법입니다. 이 접근법은 일반적으로 비지도 학습 방식을 통해 수행되며, 복잡하고 다양한 환경에서 발생하는 문제 해결에도 적합합니다. 하지만 상향식 접근법은 분석 대상이 명확할 때가 아니라, 명확하지 않을 때 사용됩니다. 즉, 잘 정의되지 않은 문제나 비즈니스 니즈를 찾아내는 데 사용됩니다. 따라서 상향식 접근법을 설명하는 옳지 않은 문장은 1번입니다.</p>"]},"rate":79,"rateN":10291},{"id":"62460","number":17,"category":"데이터 분석 기획","type":"choice","subject":"과제 중심적인 접근 방식으로 진행되는 특징으로 알맞지 않은 것은?","choices":[{"n":1,"html":"Speed & Test"},{"n":2,"html":"Quick-Win"},{"n":3,"html":"Accuracy & Deploy"},{"n":4,"html":"Problem solving"}],"answer":[3],"explain":{"ai":["<p>과제 중심적인 접근 방식은 빠르게 결과를 도출하고 문제를 해결하는 것을 목표로 합니다. 따라서 빠른 성과를 내는 것을 강조하는 Quick-Win, 테스트와 속도를 중요시하는 Speed &amp; Test, 문제 해결을 중시하는 Problem solving은 모두 과제 중심적인 접근 방식의 특징과 부합합니다. 그러나 Accuracy &amp; Deploy는 정확성과_deploy를 강조하며, 이는 과제 중심적인 접근 방식의 특징을 완벽하게 반영하지는 못합니다. 과제 중심적인 접근 방식은 빠른 진행과 결과 도출을 중요시하기 때문입니다. 따라서 Accuracy &amp; Deploy가 과제 중심적인 접근 방식의 특징으로는 알맞지 않습니다.</p>"]},"rate":76,"rateN":10568},{"id":"62461","number":18,"category":"데이터 분석 기획","type":"choice","subject":"하향식 접근 방식의 수행 내용으로 옳지 않은 것은?","choices":[{"n":1,"html":"문제 탐색"},{"n":2,"html":"프로토 타이핑"},{"n":3,"html":"문제 정의"},{"n":4,"html":"타당성 검토"}],"answer":[2],"explain":{"ai":["<p>하향식 접근 방식은 데이터 분석을 위한 전반적인 프로세스를 계획하고 진행하는 방식입니다. 주로 처음부터 전체적인 목표와 방향을 설정하고 세부적으로 나아가는 방식을 말합니다. </p>\n<p>문제 탐색은 데이터 분석의 처음 단계로 문제를 찾고 정의하는 과정입니다. 문제 정의는 문제 탐색의 결과를 바탕으로 문제를 명확히 하는 과정입니다. 타당성 검토는 분석이 완료된 후에 분석 결과가 타당한지 검토하는 과정으로 분석 계획 단계에서 전체적인 타당성을 검토하는 것도 포함됩니다.</p>\n<p>그러나 프로토 타이핑은 하향식 접근 방식의 전형적인 수행 내용은 아닙니다. 프로토 타이핑은 보통 상향식 접근 방식에서 사용되는데 구체적인 문제 해결을 위해 hızla 설계하고 테스트하는 과정을 거치는 것입니다. </p>\n<p>따라서 하향식 접근 방식의 수행 내용으로 옳지 않은 것은 프로토 타이핑입니다.</p>"]},"rate":72,"rateN":10937},{"id":"62462","number":19,"category":"데이터 분석 기획","type":"choice","subject":"빅데이터 분석 방법론의 분석 기획 단계에서 수행하는 주요 Task로 옳은 것은","choices":[{"n":1,"html":"비즈니스의 이해 및 범위 설정"},{"n":2,"html":"필요 데이터 정의"},{"n":3,"html":"모델 적용 및 운영 방안 수립"},{"n":4,"html":"모델 발전 계획 수립"}],"answer":[1],"explain":{"ai":["<p>분석 기획 단계에서는 주로 프로젝트의 초기 방향성과 목표를 명확히 설정하는 것이 핵심이다. 주어진 보기들 중에서:</p>\n<ol>\n<li>\n<p><strong>비즈니스의 이해 및 범위 설정</strong>: 이는 분석 기획의 핵심 Task이다. 비즈니스 목표와 문제를 정확히 이해하고 분석의 범위를 명확히 하는 것이 초기 단계에서 필수적이다. 이를 통해 후속 단계에서 필요한 데이터 수집과 분석 방향을 올바르게 설정할 수 있다.</p>\n</li>\n<li>\n<p><strong>필요 데이터 정의</strong>: 이는 분석 설계나 실행 단계에 더 가깝다. 기획 단계에서는 데이터의 중요성을 인식하고 대략적인 필요성을 파악할 수 있지만, 구체적인 데이터 정의는 이후 단계에서 이루어진다.</p>\n</li>\n<li>\n<p><strong>모델 적용 및 운영 방안 수립</strong>: 이 Task는 분석 설계와 실행, 그리고 운영 단계에 해당한다. 기획 단계에서는 이러한 구체적인 모델 적용 계획보다는 큰 그림을 그리는 것이 주 목표이다.</p>\n</li>\n<li>\n<p><strong>모델 발전 계획 수립</strong>: 역시 후속 단계의 작업으로, 초기 기획 단계에서는 현재 문제 해결을 위한 기본적인 분석 프레임워크를 설정하는 것이 우선이다.</p>\n</li>\n</ol>\n<p>따라서, 분석 기획 단계에서 가장 적절한 Task는 <strong>1번: 비즈니스의 이해 및 범위 설정</strong>이다.</p>"]},"rate":62,"rateN":11772},{"id":"62463","number":20,"category":"데이터 분석 기획","type":"choice","subject":"데이터 분석 기획 유형에 관한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"분석 대상을 알고, 분석 방식도 아는 경우 개선을 통한 최적화 유형을 적용한다."},{"n":2,"html":"최적화, 솔루션, 관찰, 발견의 4가지 분석 주제 유형으로 이루어져 있다."},{"n":3,"html":"분석 대상을 알고 분석 방식을 모르는 경우 솔루션을 찾아내는 방식을 적용한다."},{"n":4,"html":"발견은 분석대상을 모르고, 분석 방식도 모르는 경우 적용한다."}],"answer":[2],"explain":{"ai":["<p>정답은 2번입니다. 데이터 분석 기획 유형은 주로 분석의 목표와 초기 지식 수준에 따라 구분되며, 일반적으로 최적화, 솔루션 도출, 관찰, 발견 등 4가지로 분류되긴 하지만, 문제에서 제시된 대로 단순히 '4가지 분석 주제 유형으로 이루어져 있다'는 설명만으로는 전체적인 분석 유형의 범위와 구체적인 적용 기준을 정확히 전달하지 못합니다. </p>\n<p>정확한 이해를 위해서는 각 유형의 구체적인 적용 조건이 중요합니다:</p>\n<ul>\n<li><strong>최적화</strong>: 분석 대상과 방법을 알고 있는 상황에서 성능 개선을 목표로 합니다.</li>\n<li><strong>솔루션 도출</strong>: 분석 대상은 명확히 알고 있으나 방법이 불분명한 경우, 문제 해결 방안을 찾는 데 초점을 맞춥니다.</li>\n<li><strong>관찰</strong>: 분석 대상은 명확히 알고 있지만, 그 결과나 패턴을 더 깊이 이해하기 위해 수행됩니다.</li>\n<li><strong>발견</strong>: 가장 미지의 영역으로, 분석 대상과 방법 모두 불분명한 상태에서 새로운 패턴이나 인사이트를 찾는 과정입니다.</li>\n</ul>\n<p>따라서 2번은 단순히 유형의 개수만을 언급하고 구체적인 적용 기준이나 의미를 포괄적으로 설명하지 못해 부정확하다고 볼 수 있습니다.</p>"]},"rate":65,"rateN":11374},{"id":"62464","number":21,"category":"데이터 분석","type":"choice","subject":"다음이 설명하는 표본 추출 방법으로 알맞은 것은","extra":"<pre class=\"contents\">모집단을 상이한 집단으로 나누고 각 집단에서 무작위로 표본을 추출하는 방법</pre>","choices":[{"n":1,"html":"단순 무작위 추출법"},{"n":2,"html":"계통 추출법"},{"n":3,"html":"군집 추출법"},{"n":4,"html":"층화 추출법"}],"answer":[4],"explain":{"ai":["<p>모집단을 상이한 집단으로 나누고 각 집단에서 무작위로 표본을 추출하는 방법은 층화 추출법이다. 이 방법은 모집단을 여러 개의 하위 집단으로 나누고 각 하위 집단에서 무작위로 표본을 선정하여 표본을 구성한다. 이렇게 하면 각 하위 집단이 적절하게 대표되면서도 전체 모집단의 특성을 유지할 수 있다. 따라서 이 설명에 알맞은 표본 추출 방법은 4번의 층화 추출법이다.</p>"]},"rate":43,"rateN":13962},{"id":"62465","number":22,"category":"데이터 분석","type":"choice","subject":"주성분 수의 선택 방법에 대한 설명으로 가장 옳지 않은 것은?","choices":[{"n":1,"html":"주성분들이 설명하는 총 분산의 비율이 70~90% 사이가 되는 주성분의 개수를 선택할 수도 있다."},{"n":2,"html":"고유값이 1에 가까운 값을 선택 한다."},{"n":3,"html":"스크리 플롯(Scree Plot)을 통해서 주성분의 분산 감소가 급격하게 줄어들어, 주성분의 개수를 늘릴때 얻게 되는 정보의 양이 상대적으로 미미한 지점에서 주성분의 개수를 정할 수 있다."},{"n":4,"html":"전체 변이 공헌도 방법은 고유값 평균 및 스크리 플롯(Scree Plot) 방법보다 항상 우수하다."}],"answer":[4],"explain":{"ai":["<p>정답은 4번입니다. 주성분 수의 선택 방법 중에서 각 방법은 상황과 목적에 따라 장단점이 다르므로, \"전체 변이 공헌도 방법\"이 항상 다른 방법들보다 우수하다고 단정 짓는 것은 부적절합니다.</p>\n<p>1번은 총 분산 설명 비율을 기준으로 주성분 수를 결정하는 것이 일반적인 방법 중 하나입니다. \n2번은 고유값이 크면 해당 주성분이 데이터의 변동을 잘 설명한다는 개념에 기반하고 있습니다.\n3번은 스크리 플롯을 사용해 분산 감소의 기울기 변화를 관찰하고, 그 지점에서 주성분의 개수를 결정하는 효과적인 방법을 설명합니다.</p>\n<p>하지만 4번은 잘못된 주장입니다. 전체 변이 공헌도 방법이 고유값 평균이나 스크리 플롯 방법에 비해 항상 더 나은 결과를 보장하지 않습니다. 각 방법의 적합성은 분석의 구체적인 목표, 데이터 특성 등에 따라 달라집니다. 그러므로 모든 상황에서 특정 방법을 우월하게 평가하는 것은 정확하지 않습니다.</p>"]},"rate":67,"rateN":10105},{"id":"62466","number":23,"category":"데이터 분석","type":"choice","subject":"의사결정 나무 분리 기준인 엔트로피 지수의 계산식은?","choices":[{"n":1,"html":"엔트로피 지수(Entropy index)<br>&nbsp;<img src='data:image/png;base64,'>"},{"n":2,"html":"엔트로피 지수(Entropy index)<br>&nbsp;<img src='data:image/png;base64,'>"},{"n":3,"html":"엔트로피 지수(Entropy index)<br>&nbsp;<img src='data:image/png;base64,'>"},{"n":4,"html":"엔트로피 지수(Entropy index)<br>&nbsp;<img src='data:image/png;base64,'>"}],"answer":[1],"rate":59,"rateN":10536},{"id":"62467","number":24,"category":"데이터 분석","type":"choice","subject":"확률에 대한 설명으로 가장 적합하지 않은 것은?","choices":[{"n":1,"html":"각 사건의 확률은 0~1이다.(확률은 0이상의 값을 가진다.)"},{"n":2,"html":"표본 공간(S)에서 발생 가능한 모든 사건의 확률의 합은 1이다."},{"n":3,"html":"A와 B가 독립 사건인 경우, 각 독립사건들의 확률의 합은 합집합의 확률과 동일하다."},{"n":4,"html":"전체 표본 중 독립적인 것을 근원 사건이라 한다."}],"answer":[3],"explain":{"ai":["<p>아래는 데이터 분석에서 확률의 정의와 특징에 대한 설명이다. \n각 사건의 확률은 0 이상 1 이하의 값을 갖는다. \n또한 표본 공간에서 발생 가능한 모든 사건의 확률의 합은 1이다. \n이벤트가 독립적이라는 것은 두 사건이 서로 영향을 미치지 않는다는 것을 의미한다. \n즉,_event A와 event B가 독립적인 경우, P(A ∩ B) = P(A) * P(B)이다. \n이러한 특성을 이용하여 확률을 계산하고 데이터 분석에 활용할 수 있다.</p>"]},"rate":56,"rateN":10986},{"id":"62469","number":25,"category":"데이터 분석","type":"choice","subject":"아래 데이터는 닭의 성장률에 대한 다양한 사료 보충제의 효과를 측정하고 비교하기 위한 사료 유형 별 닭의 무게 데이터이다. summary함수 결과에 대한 해석  옳지 않은 것은?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"feed는 범주형 데이터이다."},{"n":2,"html":"feed의 사료 중 soybean의 수가 가장 많다."},{"n":3,"html":"range(chickwts$weight) 결과는 108 423이다."},{"n":4,"html":"weight의 평균값은 258.0이다"}],"answer":[4],"rate":82,"rateN":8988},{"id":"62470","number":26,"category":"데이터 분석","type":"choice","subject":"계층적 군집 방법으로 가장 알맞지 않은 것은?","choices":[{"n":1,"html":"단일 연결법"},{"n":2,"html":"완전 연결법"},{"n":3,"html":"평균 연결법"},{"n":4,"html":"편차 연결법"}],"answer":[4],"explain":{"ai":["<p>계층적 군집 방법은 데이터를 어떤 기준에 따라 군집으로 나누는 방법입니다. 단일 연결법, 완전 연결법, 평균 연결법은 모두 계층적 군집 방법입니다. 단일 연결법은 가장 가까운 데이터끼리 군집으로 묶고, 완전 연결법은 가장 먼 데이터끼리 군집으로 묶으며, 평균 연결법은 데이터들 간의 평균 거리를 기준으로 군집으로 묶습니다.</p>\n<p>편차 연결법은 계층적 군집 방법이 아니라 분히추적 군집 방법에 더 가깝습니다. 편차 연결법은 데이터들의 분산이나 표준편차를 통해 군집을 나누기 때문에 계층적 군집 방법으로 보기는 어렵습니다. 따라서 계층적 군집 방법으로 가장 알맞지 않은 것은 편차 연결법인 4번입니다.</p>"]},"rate":54,"rateN":11061},{"id":"62471","number":27,"category":"데이터 분석","type":"choice","subject":"분해시계열의 요인으로 알맞지 않은 것은?","choices":[{"n":1,"html":"추세 요인"},{"n":2,"html":"계절 요인"},{"n":3,"html":"환경 요인"},{"n":4,"html":"순환 요인"}],"answer":[3],"explain":{"ai":["<p>분해시계열의 요인은 시계열 데이터에서 변동을 설명하는 구성 요소를 뜻한다. 시계열 데이터는 시간의 경과에 따라 발생하는 데이터로 다양한 패턴과 요인을 포함한다. 분해시계열의 일반적인 요인은 다음과 같다. </p>\n<p>첫 번째는 추세 요인으로 시간의 경과에 따라 데이터가 일정한 방향으로 증가하거나 감소하는 경향을 의미한다. 두 번째는 계절 요인으로 데이터가 특정 시기에 따라 규칙적으로 변동하는 패턴을 말한다. 세 번째는 순환 요인으로 경제적으로 불황이나 호황 등의 순환적인 변동을 통해 데이터가 영향을 받는 것을 뜻한다.</p>\n<p>환경 요인은 분해시계열의 일반적인 요인이 아니다. 분해시계열은 주로 내부적 요인에 의해 형성되는 패턴을 설명하는데 환경 요인은 외부의 특정 사건이나 조건이 데이터에 미치는 영향이다. 따라서 분해시계열의 요인으로 알맞지 않은 것은 환경 요인이다.</p>"]},"rate":72,"rateN":9631},{"id":"62472","number":28,"category":"데이터 분석","type":"choice","subject":"다음 수식으로 구할 수 있는 데이터간 거리는?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"유클리드 거리"},{"n":2,"html":"표준화 거리"},{"n":3,"html":"마할라노비스 거리"},{"n":4,"html":"민코프스키 거리(민코우스키 거리)"}],"answer":[4],"rate":50,"rateN":11544},{"id":"62473","number":29,"category":"데이터 분석","type":"choice","subject":"다음 중 의사결정나무와 가장 관련 없는 용어는?","choices":[{"n":1,"html":"카이제곱 통계량"},{"n":2,"html":"지니 지수"},{"n":3,"html":"엔트로피 지수"},{"n":4,"html":"퍼셉트론(Perceptron)"}],"answer":[4],"explain":{"ai":["<p>의사결정나무는 데이터를 분류하거나 예측하기 위해 계층적인 구조를 만드는 모델로, 주로 정보의 불확실성을 줄이는 기준을 사용한다. </p>\n<ul>\n<li><strong>지니 지수</strong>와 <strong>엔트로피 지수</strong>는 각각 노드의 불순도를 측정하는 지표로, 의사결정나무에서 분할 기준으로 자주 사용된다. </li>\n<li><strong>카이제곱 통계량</strong>은 주로 범주형 데이터의 독립성 검정에 사용되지만, 분류 문제에서 특성의 중요도를 평가하는 데도 간접적으로 연관될 수 있다.</li>\n<li>반면, <strong>퍼셉트론</strong>은 신경망의 기본 구조로, 선형 분류 문제를 해결하는 데 주로 사용되며, 의사결정나무와는 다른 알고리즘적 접근 방식을 취한다. 따라서 의사결정나무와 가장 관련이 없는 용어는 4번, <strong>퍼셉트론(Perceptron)</strong>이다.</li>\n</ul>"]},"rate":73,"rateN":9482},{"id":"62474","number":30,"category":"데이터 분석","type":"choice","subject":"두개의 확률 변수 X, Y의 공분산에 대한 설명 중 옳지 않은 것은?","choices":[{"n":1,"html":"공분산이 양수이면 X가 증가할 때 Y도 증가한다."},{"n":2,"html":"공분산이 음수이면 X가 증가할 때 Y는 감소한다."},{"n":3,"html":"공분산의 크기는 상관계수와 동일하게 -1 ~ 1 사이의 범위를 갖는다."},{"n":4,"html":"공분산이 0이면 두 변수간에는 아무런 선형관계가 없으며 두 변수는 서로 독립적인 관계이다."}],"answer":[3],"explain":{"ai":["<p>공분산은 두개의 확률 변수 간의 선형 관계를 나타내는 측도이다. 공분산이 양수이면 두 변수가 증가할 때 함께 증가하는 경향이 있고, 음수이면 하나의 변수가 증가할 때 다른 변수는 감소하는 경향이 있다. 공분산이 0이면 두 변수간에는 선형관계가 없으며, 두 변수는 서로 독립적인 관계일 가능성이 크다. 그러나 공분산의 크기는 변수의 단위에 따라 다르기에 상관계수와 동일하게 -1 ~ 1 사이의 범위를 갖지 않는다. 따라서 공분산의 크기는 상관계수와 동일하게 -1 ~ 1 사이의 범위를 갖는다라는 설명은 옳지 않다.</p>"]},"rate":61,"rateN":10362},{"id":"62475","number":31,"category":"데이터 분석","type":"choice","subject":"아래의 F-Beta Score(지표)에 대한 설명으로 옳은 것은?","choices":[{"n":1,"html":"Beta 값이 1.0보다 크면 Percision에 비중을 두고 계산한다."},{"n":2,"html":"Beta 값이 1.0보다 작으면 Recall에 비중을 두고 계산한다."},{"n":3,"html":"Beta 값이 0.5일 경우 precision에 2배 가중치하여 평균한다."},{"n":4,"html":"Recall 값과 Precision값이 정확히 같다면 Beta에 관계없이 다른 결과가 나온다."}],"answer":[3],"explain":{"ai":["<p>F-Beta Score는 모델의 Precision과 Recall을 가중 평균으로 평가하는 지표로, Beta 값에 따라 두 지표 중 어느 쪽에 더 큰 중요성을 부여할지 조절한다.</p>\n<ul>\n<li>1번은 틀렸다. Beta 값이 1.0보다 클 때, 실제로 Recall에 더 큰 가중치를 부여하여 Recall의 중요성을 강조한다. Precision에 더 비중을 두는 것은 Beta가 0.5 이하일 때의 특징이다.</li>\n<li>2번도 틀리다. Beta 값이 1.0보다 작을 때 Precision에 더 큰 가중치를 주게 되며, Recall에 더 비중을 두는 것은 Beta가 1.0을 초과할 때의 특성이다.</li>\n<li>3번은 맞다. Beta 값이 0.5일 때, Precision에 2배의 가중치를 부여한 형태로 계산된다. 이는 Recall에 비해 Precision을 더 중요하게 여긴다는 의미다.</li>\n<li>4번은 맞지 않다. Recall과 Precision이 정확히 같을 때, Beta 값에 관계없이 F-Beta Score는 동일한 값을 가지게 된다. 즉, 모든 Beta 값에 대해 같은 결과를 보이게 되므로, 이 상황에서는 Beta의 영향이 없다.</li>\n</ul>\n<p>따라서 정답은 3번이다.</p>"]},"rate":53,"rateN":9884},{"id":"62476","number":32,"category":"데이터 분석","type":"choice","subject":"앙상블 기법에 대한 설명으로 알맞은 것은?","choices":[{"n":1,"html":"앙상블 기법을 사용하게 되면 각 모형의 상호 연관성이 높을수록 정확도가 향상된다."},{"n":2,"html":"대표적인 앙상블 기법은 배깅, 부스팅이 있다."},{"n":3,"html":"전체적인 예측값의 분산을 유지하여 정확도를 높일 수 있다."},{"n":4,"html":"랜덤 포레스트는 앙상블 기법 중 유일한 비지도 기법이다."}],"answer":[2],"explain":{"ai":["<p>앙상블 기법은 여러 개의 모델을 결합하여 더 나은 성능을 얻는 기법입니다. 여러 모델의 예측값을 결합하면 오차를 감소시키고 성능을 향상할 수 있습니다. 앙상블 기법 중 대표적인 법은 배깅과 부스팅입니다. 배깅은 여러 개의 모델을 생성하여 예측값을 결합하는 방식이고 부스팅은 순차적으로 모델을 생성하고 연합하여 예측하는 방식입니다. 랜덤 포레스트도 앙상블 기법 중 하나로 여러 개의 의사결정 트리를 생성하여 예측값을 결합합니다. nhưng 랜덤 포레스트가 유일한 비 督학 기법이라는 것은 맞지 않습니다.</p>"]},"rate":67,"rateN":10089},{"id":"62477","number":33,"category":"데이터 분석","type":"choice","subject":"다음 중 통계적 가설검정에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"귀무가설이 사실일 때 이 귀무가설을 기각함으로써 발생하는 오류를 유의수준이라 한다."},{"n":2,"html":"귀무가설이 거짓일 경우, 이를 옳지 않다고 판단하는 확률을 검정력이라 한다."},{"n":3,"html":"사실인 귀무가설을 기각했을 때 발생하는 오류를 제 2종 오류라 한다."},{"n":4,"html":"p-value(유의확률)이 클수록 귀무가설을 채택하는 것으로 해석한다."}],"answer":[3],"explain":{"ai":["<p>3번이 옳지 않은 설명입니다. 제 2종 오류는 실제로 귀무가설이 거짓임에도 불구하고 이를 채택하거나 기각하지 못하는 오류를 의미합니다. 정확하게는, 귀무가설이 사실이 아닌데 이를 잘못 유지하는 것을 <strong>제 2종 오류</strong> 또는 <strong>β 오류</strong>라고 부릅니다. 따라서, \"사실인 귀무가설을 기각했을 때\"라는 설명은 제 1종 오류(α 오류)를 설명하는 것이 맞고, 이는 제 2종 오류의 정의와 맞지 않아 잘못된 설명입니다. </p>\n<p>다른 보기들은 다음과 같이 올바르게 설명됩니다:</p>\n<ol>\n<li>유의수준은 귀무가설이 사실일 때 이를 잘못 기각할 확률(제 1종 오류)을 가리킵니다.</li>\n<li>검정력은 귀무가설이 거짓일 때 이를 올바르게 기각할 확률을 의미합니다.</li>\n<li>p-value가 클수록 귀무가설을 기각할 근거가 약해지므로, 통계적으로는 더 큰 p-value는 귀무가설을 기각하지 않고 유지하는 방향으로 해석됩니다.</li>\n</ol>"]},"rate":59,"rateN":10554},{"id":"62478","number":34,"category":"데이터 분석","type":"choice","subject":"K-means 군집분석에 대한 설명으로 옳은 것은?","choices":[{"n":1,"html":"군집에서 가장 중심에 위치한 객체를 사용하여 k개의 군집을 찾게 된다."},{"n":2,"html":"K-Medoids 알고리즘에 비해 노이즈 처리에 우수하고 연산량이 많다."},{"n":3,"html":"초승달 모양(Crecent Shaped) 데이터 셋에 적합하다."},{"n":4,"html":"군집 절차 수행 시 군집 수 K는 초기에 설정되어야 한다."}],"answer":[4],"explain":{"ai":["<p>정답은 4번입니다.</p>\n<p>K-means 군집분석의 핵심 특징은 다음과 같습니다:</p>\n<ul>\n<li><strong>4번</strong>: 군집 분석을 시작할 때, 분석자가 군집의 수 K를 미리 지정해야 합니다. 이는 알고리즘이 이 지정된 K개의 군집을 형성하는 데 기반합니다.</li>\n</ul>\n<p>다른 옵션들은 다음과 같은 이유로 부적절합니다:</p>\n<ul>\n<li>\n<p><strong>1번</strong>: K-means는 각 군집의 중심(centroid)을 계산하는데, 이 중심은 군집 내 모든 데이터 객체의 평균 위치를 나타내며, 가장 중심에 위치한 단일 객체를 사용하는 것이 아닙니다.</p>\n</li>\n<li>\n<p><strong>2번</strong>: K-means는 일반적으로 수치적 데이터에 대해 효과적이지만, 노이즈에 대한 민감도가 높고 계산 복잡도가 낮은 편입니다. 반면 K-Medoids는 더 강건하게 노이즈를 처리할 수 있지만, 연산량은 상황에 따라 다를 수 있습니다. 따라서 \"연산량이 많다\"는 일반화하기 어렵습니다.</p>\n</li>\n<li>\n<p><strong>3번</strong>: K-means는 구형 또는 대체로 균일한 분포의 데이터에 잘 작동하지만, 초승달 모양(crescent shaped)과 같은 복잡한 형태의 데이터 셋에서는 군집 경계를 정확히 구분하는 데 어려움을 겪을 수 있습니다. 이런 경우 다른 알고리즘이 더 적합할 수 있습니다.</p>\n</li>\n</ul>"]},"rate":61,"rateN":10191},{"id":"62479","number":35,"category":"데이터 분석","type":"choice","subject":"아래 오분류표에서 재현율(Recall)로 가장 알맞은 것은?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"3/10"},{"n":2,"html":"2/5"},{"n":3,"html":"1/3"},{"n":4,"html":"7/11"}],"answer":[1],"rate":65,"rateN":9089},{"id":"62480","number":36,"category":"데이터 분석","type":"choice","subject":"확률 질량 함수의 확률변수 X의 기대값은?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"10/6"},{"n":2,"html":"11/6"},{"n":3,"html":"12/6"},{"n":4,"html":"13/6"}],"answer":[4],"rate":76,"rateN":8867},{"id":"62481","number":37,"category":"데이터 분석","type":"choice","subject":"군집분석 시 데이터의 단위가 다를 경우 사용하는 기법으로 알맞은 것은?","choices":[{"n":1,"html":"Elimination"},{"n":2,"html":"Sampling"},{"n":3,"html":"Averaging"},{"n":4,"html":"Scaling"}],"answer":[4],"explain":{"ai":["<p>군집분석은 데이터를 특성에 따라 몇몇의 군집으로 나누는 분석기법입니다. 하지만 데이터의 단위가 다를 경우 데이터 간의 비교가 어려워집니다. 이러한 문제를 해결하기 위해 사용하는 기법이 스케일링입니다. 스케일링은 데이터의 범위를 조정하여 동일한 단위로 만드는과정입니다. 이를 통해 데이터 간의 비교가 가능해지고 군집분석의 결과가 신뢰성 있게 됩니다. 따라서 데이터의 단위가 다를 경우 사용하는 기법으로 스케일링이 적합합니다.</p>"]},"rate":72,"rateN":9434},{"id":"62482","number":38,"category":"데이터 분석","type":"choice","subject":"다음 중 통계 용어에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"다른 변수의 영향을 받는 변수를 설명 변수라고 한다."},{"n":2,"html":"모집단의 평균을 추정하기 위해 표본 평균을 계산한다."},{"n":3,"html":"표준 편차는 데이터가 평균으로부터 떨어진 정도를 나타내는 척도이다."},{"n":4,"html":"사분위수범위는 데이터의 25%, 50%, 75%에서 25%의 값을 빼준 값이다."}],"answer":[1],"explain":{"ai":["<p>정답은 1번입니다. 설명이 잘못되었기 때문입니다.</p>\n<p>1번 설명은 부정확합니다. 실제로 <strong>설명 변수</strong>는 독립 변수를 의미하며, 그 영향을 받는 변수를 <strong>종속 변수</strong>라고 부릅니다. 따라서 다른 변수의 영향을 받는 변수를 설명 변수라고 표현하는 것은 맞지 않습니다.</p>\n<p>나머지 보기들은 올바르게 정의되어 있습니다:</p>\n<ul>\n<li>2번: 표본 평균을 통해 모집단 평균을 추정하는 것은 통계학에서 일반적인 방법입니다.</li>\n<li>3번: 표준 편차는 데이터 값들이 평균으로부터 얼마나 퍼져 있는지를 나타내는 척도입니다.</li>\n<li>4번: 사분위수 범위는 3사분위수(75% 백분위수)에서 1사분위수(25% 백분위수)를 뺀 값으로, 데이터의 중앙 50% 범위를 나타냅니다. 여기서 25% 값을 빼준다는 표현은 약간 혼동스러울 수 있으나, 핵심 개념은 맞습니다. 하지만 주어진 문제에서 가장 명확히 잘못된 설명은 1번입니다.</li>\n</ul>"]},"rate":52,"rateN":11376},{"id":"62483","number":39,"category":"데이터 분석","type":"choice","subject":"다음 중 시계열 모형에 대한 설명으로 옳은 것은?","choices":[{"n":1,"html":"ARIMA의 약어는 AutoRegressive Improved Moving Average 이다."},{"n":2,"html":"ARIMA 모형에서 P=0일 때, IMA(d,q) 모형이라고 부르고, d번 차분하면 MA(q) 모형을 따른다."},{"n":3,"html":"분해시계열은 일반적인 요인을 분리하여 분석하는 방법으로 회귀분석적인 방법과는 다르게 사용한다."},{"n":4,"html":"ARIMA모형에서는 정상성을 확인할 필요가 없다."}],"answer":[2],"explain":{"ai":["<p>시계열 모형은 시간의 경과에 따른 데이터의 패턴을 분석하는 통계적 방법입니다. 정답인 2번은 ARIMA 모형의 특성을 설명하고 있습니다. ARIMA 모형은 자기회귀, 차분, 이동평균의 조합을 의미합니다. P=0일 때, 모형은 IMA(d,q)로 축약 될 수 있습니다.여기서 d는 차분의次数, q는 이동평均의次数를 나타냅니다. d번 차분을 하면 정상성을 가진 시계열로 변환하고, 그 결과는 MA(q) 모형을 따르게 됩니다. 즉, 이동평균 모형의 특성을 띄게 됩니다. </p>\n<p>옳지 않은 다른 보기들은 다음과 같은 이유로 부정될 수 있습니다. \n1번의 경우, ARIMA는 AutoRegressive Integrated Moving Average의 약자입니다. \n3번의 경우, 분해시계열은 시계열을 trend, seasonality, residuals로 분리하여 분석하는 방법으로, 실제로는 회귀분석적인 방법과 유사한 측면이 있습니다. \n4번의 경우, ARIMA모형에서는 정상성을 확인하는 것이 중요합니다. 왜냐하면 ARIMA 모형은 정상적인 시계열 데이터를 가정하기 때문입니다. 비정상적인 데이터의 경우, 차분과 같은 전처리가 필요할 수 있습니다.</p>"]},"rate":53,"rateN":10633},{"id":"62484","number":40,"category":"데이터 분석","type":"choice","subject":"다음 중 데이터의 정규성을 확인하기 위한 방법으로 알맞지 않은 것은?","choices":[{"n":1,"html":"Q-Q plot"},{"n":2,"html":"결정 계수"},{"n":3,"html":"히스토그램"},{"n":4,"html":"첨도와 왜도"}],"answer":[2],"explain":{"ai":["<p>데이터의 정규성을 확인하는 방법에는 여러 가지가 있다. Q-Q plot은 정규분포와 데이터를 비교하여 정규성을 확인하는 시각적 방법이다. 히스토그램은 데이터의 분포를 그래프로 표현하여 정규성을 직관적으로 확인할 수 있다. 첨도와 왜도는 데이터의 분포 형태를 수치적으로 나타내는 통계量으로, 정규성 확인에 사용된다.</p>\n<p>그러나 결정 계수는 회귀 분석에서 모델의 설명력을 측정하는 지표로, 데이터의 정규성과 직접적인 관련이 없다. 즉, 결정 계수는 모델의 적합도와 예측력을 평가하지만, 데이터가 정규분포를 따르는지 여부를 확인하는 데 사용되는 것은 아니다. 따라서 데이터의 정규성을 확인하기 위한 방법으로는 알맞지 않다.</p>"]},"rate":50,"rateN":11316},{"id":"62485","number":41,"category":"데이터 분석","type":"choice","subject":"다음 중 선형회귀모형이 통계적으로 유의미한지 평가하는 통계량으로 옳은 것은?","choices":[{"n":1,"html":"F-Statistics"},{"n":2,"html":"Chi-Statistics"},{"n":3,"html":"T-Statistics"},{"n":4,"html":"R-Square"}],"answer":[1],"explain":{"ai":["<p>선형회귀모형의 유의미성을 평가할 때는 F-Statistics를 사용한다. F-Statistics는 전체 모델의 설명력을 평가하는 데 사용되며 모델의 회귀계수들이 전체적으로 유의미한지를 나타낸다. 즉, F-통계량은 모형의 설명력이 우연에 의한 것인지, 실제로 유의미한지 판단하는 데 사용되는 통계량이다.</p>\n<p>다른 옵션들은 다음과 같다. Chi-Statistics는 주로 카이제곱 검정을 할 때 사용되고, T-Statistics는 개별 회귀계수의 유의미성을 평가하는 데 사용된다. R-Square는 모델의 설명력을 평가하는 데 사용되지만 모델의 유의미성 여부를 직접적으로 평가하는 데는 사용되지 않는다. </p>\n<p>따라서 선형회귀모형이 통계적으로 유의미한지 평가하는 통계량으로는 F-Statistics가 사용된다.</p>"]},"rate":59,"rateN":10305},{"id":"62486","number":42,"category":"데이터 분석","type":"choice","subject":"데이터의 양이 가장 많이 발생하는 유형의 척도로 알맞은 것은?","choices":[{"n":1,"html":"명목 척도"},{"n":2,"html":"순서 척도"},{"n":3,"html":"등간 척도"},{"n":4,"html":"비율 척도"}],"answer":[4],"explain":{"ai":["<p>データ의 양이 가장 많이 발생하는 유형의 척도는 비율 척도이다. 비율 척도는 자연적인 0이라는 점과 같은 간격을 가지고 있어 수치적인 연산이 가능하다. 예를 들어, 나이, 키, 몸무게와 같은 데이터는 비율 척도로 측정할 수 있다. 이러한 데이터는 통계적인 분석과 계산에 용이하기 때문에 데이터 분석에서 매우 중요한 역할을 한다.</p>"]},"rate":56,"rateN":10871},{"id":"62487","number":43,"category":"데이터 분석","type":"choice","subject":"상관계수에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"피어슨 상관계수는 두 변수 간의 선형적인 관계의 강도를 측정한다."},{"n":2,"html":"피어슨 상관계수는 두 변수의 원래 값을 사용하여 계산된다."},{"n":3,"html":"스피어만 상관계수는 모수적 관계에서 두 변수 간의 단조적인 관계의 강도를 측정한다."},{"n":4,"html":"피어슨 상관계수가 0이면 선형관계가 없다."}],"answer":[3],"explain":{"ai":["<p>피어슨 상관계수는 두 변수 간의 선형적인 관계의 강도를 측정한다. 피어슨 상관계수는 두 변수의 원래 값을 사용하여 계산된다고도 한다. 피어슨 상관계수가 0이면 선형관계가 없다고도 한다. \n지만 스피어만 상관계수는 비모수적 관계에서 두 변수 간의 단조적인 관계의 강도를 측정한다. 따라서 3번은 옳지 않은 설명이다.</p>"]},"rate":52,"rateN":10927},{"id":"62488","number":44,"category":"데이터 분석","type":"choice","subject":"시계열 데이터의 정상성(Stationary)에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"평균이 일정하다."},{"n":2,"html":"시계열 자료는 독립성을 충족해야 한다."},{"n":3,"html":"분산이 시점에 의존하지 않는다."},{"n":4,"html":"공분산은 단지 시차에만 의존하고, 시점 자체에는 의존하지 않는다."}],"answer":[2],"explain":{"ai":["<p>정상성은 시계열 数据의 특성 중 하나로, 時間의 흐름에 따라 数据의 분포가 변하지 않는 것을 말한다. 즉, 데이터의 평균, 분산, 공분산 등이 시간에 따라 일정해야 한다. </p>\n<p>시계열 数据의 정상성에 대한 설명으로 옳지 않은 것은 독립성이다. 독립성은 각각의 관측치가 서로 독립적이어야 한다는 것으로, 시계열 数据의 정상성과는 관련이 없다. 실제로 많은 시계열 数据는 자기 상관성이 존재하기 때문에 독립성은 충족되지 않는다. </p>\n<p>따라서 평균이 일정하고, 분산이 시점에 의존하지 않으며, 공분산은 단지 시차에만 의존하는지는 정상성의 조건이지만, 독립성은 관련이 없다.</p>"]},"rate":41,"rateN":12494},{"id":"62489","number":45,"category":"데이터 분석","type":"choice","subject":"다음 중 회귀분석에서 모형의 설명력을 확인하기 위해 사용되는 결정 계수의 특성으로 옳지 않은 것은?","choices":[{"n":1,"html":"결정 계수는 0에서 1의 값을 가진다."},{"n":2,"html":"높은 값을 가질수록 측정된 회귀식의 설명력이 높다."},{"n":3,"html":"총 변동에서 추정된 회귀식에 의해 설명되는 변동의 비율로 나타낼 수 있다."},{"n":4,"html":"종속 변수와 독립 변수 사이의 표본 상관 계수 값과 같다."}],"answer":[4],"explain":{"ai":["<p>회귀분석에서 결정 계수는 모형의 설명력을 확인하는 데 사용됩니다. 결정 계수는 0에서 1의 값을 가집니다. 높은 값을 가질수록 측정된 회귀식의 설명력이 높으며, 총 변동에서 추정된 회귀식에 의해 설명되는 변동의 비율로 나타낼 수 있습니다. 하지만 결정 계수는 종속 변수와 독립 변수 사이의 표본 상관 계수 값과 같지 않습니다. 결정 계수는 상관 계수와 다르며, 독립 변수가 종속 변수를 얼마나 잘 설명하는지 측정하는 度로 사용됩니다. 따라서 4번이 옳지 않은 특성입니다.</p>"]},"rate":65,"rateN":9641},{"id":"62490","number":46,"category":"데이터 분석","type":"choice","subject":"선형회귀모형이 오차항에 가정조건으로 옳은 것은?","choices":[{"n":1,"html":"독립성, 선형성, 등분산성"},{"n":2,"html":"독립성, 등분산성, 정규성"},{"n":3,"html":"정규성, 효율성, 등분산성"},{"n":4,"html":"정규성, 편의성, 독립성"}],"answer":[2],"explain":{"ai":["<p>선형회귀모형은 통계학에서 데이터를 분석하기 위한 중요한 도구로 사용됩니다. 이 모형은 오차항에 대한 여러 가지 가정조건을 가지고 있는데, 이 중에 독립성, 등분산성, 정규성은 가장 일반적인 가정입니다.</p>\n<p>독립성은 오차들이 서로 독립적이라는 것을 의미하며, 등분산성은 오차들이同じ 분산을 가지고 있다는 것을 의미합니다. 정규성은 오차들이 정규분포를 따른다는 것을 의미합니다. 이러한 가정들이 만족되면 선형회귀모형의 결과가 정확하고 신뢰할 수 있다는 것을 의미합니다.</p>\n<p>따라서 선형회귀모형의 오차항에 대한 가정조건으로 독립성, 등분산성, 정규성이 옳은 선택입니다.</p>"]},"rate":63,"rateN":10050},{"id":"62491","number":47,"category":"데이터 분석","type":"choice","subject":"아래 설명에 해당하는 용어로 알맞은 것은?","extra":"<pre class=\"contents\">다층 신경망 모형에서 은닉 층의 개수를 너무 많이 설정하면 역전파 과정에서 앞쪽 은닉층의 가중치가 조정되지 않아, 신경망에 대한 학습이 제대로 되지 않는 현상</pre>","choices":[{"n":1,"html":"기울기소실 문제"},{"n":2,"html":"과적합"},{"n":3,"html":"활성화 함수"},{"n":4,"html":"신경망 레이어 소실"}],"answer":[1],"explain":{"ai":["<p>다층 신경망 모형에서 은닉 층의 개수를 너무 많이 설정하면 역전파 과정에서 앞쪽 은닉층의 가중치가 조정되지 않아 신경망에 대한 학습이 제대로 되지 않는 현상을 기울기소실 문제라고 한다. 기울기소실 문제는 신경망 모형이 복잡해질수록 발생할 가능성이 높아진다. 이는 역전파 과정에서 오류를 전파하는 기울기가 점차적으로 소실되기 때문에 발생한다. 이러한 문제를 해결하기 위해 다양한 기법들이 활용되고 있다. 이러한 이유로 1번이 정답이다.</p>"]},"rate":52,"rateN":11061},{"id":"62492","number":48,"category":"데이터 분석","type":"choice","subject":"아래 보기의 회귀모델에 대한 설명 중 옳지 않은 것은?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"추정된 회귀식은 weight = 24.4654 + 79879*time와 같다."},{"n":2,"html":"F=통계량 : 232.7, p-값: 2.974e-08으로 보아 유의수준 5%하에서 추정된 회귀 모형이 통계적으로 매우 유의하다."},{"n":3,"html":"time이 1 증가할 때, weight가 5.99만큼 증가한다."},{"n":4,"html":"결정계수 또한 0.9588로 매우 높은 값을 보이므로 이 회귀식이 데이터를 약 96% 정도로 설명하고 있다."}],"answer":[3],"rate":71,"rateN":9026},{"id":"62493","number":49,"category":"데이터 분석","type":"choice","subject":"카이제곱 통계량의 에측 표본과 실제 표본의 차이와 검정 통계량에 따른 유의확률의 변화로 옳은 것은?","choices":[{"n":1,"html":"카이제곱 통계량을 이용한 적합도 검정은 여러 범주형 변수에 대해 관측 값들이 어떤 이론이나 이론적 분포를 따르고 있는지를 검정하는 방법이다."},{"n":2,"html":"데이터의 정규성을 검정하기 위해 오차항이 정규분포를 추종하는지 알아보는 검정방법이다."},{"n":3,"html":"예측 표본과 실제 표본의 차이가 많을 때, 도수가 낮아지고 검정 통계량이 높아져 유의 확률이 낮아진다."},{"n":4,"html":"각 데이터 포인트와 이론적인 분포 간의 차이를 측정하여 이 차이를 기반으로 검정 통계량을 계산한다."}],"answer":[3],"explain":{"ai":["<p>예측 표본과 실제 표본의 차이가 많을 때는 카이제곱 통계량이 높아진다. 이는 실제와 예측값 간의 차이가 클수록 통계량 값도 커지기 때문이다. 카이제곱 통계량이 높아질수록 유의 확률은 낮아진다. 유의 확률이 낮다는 것은 두 집단 간의 차이가 우연에 의한 것이 아니라는 것을 의미한다. </p>\n<p>카이제곱 검정은 두 변수 간의 독립성 여부를 확인하는 것으로, 예측과 실제 차이가 많을수록 통계량 값은 커지고, 유의 확률은 낮아지게 된다. 즉 예측과 실제 간의 차이가 많으면 검정 통계량은 커지고, 그에 따라 유의 확률은 낮아지게 되므로 3번이 정답이다.</p>"]},"rate":43,"rateN":11347},{"id":"62494","number":50,"category":"데이터 분석","type":"choice","subject":"인공신경망 함수에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"인공신경망 함수는 여러 개의 뉴런이 연결된 구조를 가지고 있으며, 각 뉴런은 입력값에 따라 비선형적인 변환을 수행한다."},{"n":2,"html":"쌍곡탄젠트 함수는 0~1 사이의 값을 출력하며 시그모이드 함수와 관련이 있다."},{"n":3,"html":"인공신경망 함수는 활성화 함수를 사용하여 입력값을 출력값으로 변환한다."},{"n":4,"html":"대표적인 인공신경망 함수로는 시그모이드 함수, 쌍곡탄젠트 함수, 렐루 함수 등이 있다."}],"answer":[2],"explain":{"ai":["<p>인공신경망 함수는 여러 개의 뉴런이 연결된 구조를 가지고 있으며, 각 뉴런은 입력값에 따라 비선형적인 변환을 수행한다. 인공신경망 함수는 활성화 함수를 사용하여 입력값을 출력값으로 변환한다. 대표적인 인공신경망 함수로는 시그모이드 함수, 쌍곡탄젠트 함수, 렐루 함수 등이 있다. </p>\n<p>그러나 쌍곡탄젠트 함수는 -1~1 사이의 값을 출력한다. 이는 시그모이드 함수와 다르다. 시그모이드 함수는 0~1 사이의 값을 출력한다. 따라서 쌍곡탄젠트 함수에 대한 설명이 옳지 않은 것이다.</p>"]},"rate":56,"rateN":10327}]};